INSERT INTO "Courses" ("Id", "Title", "Description", "Price", "ThumbnailUrl", "Level", "Status", "InstructorId", "CreatedAt", "UpdatedAt", "IsPublished", "Category", "RejectionReason") VALUES (6, 'Lập trình Web Frontend Toàn Diện: HTML5, CSS3 & Modern JavaScript (2026)', 'Chương trình đào tạo toàn diện từ con số 0 đến làm chủ giao diện web chuyên nghiệp. Thực hành thiết kế giao diện chuẩn Responsive với HTML5 Semantic, CSS Flexbox & CSS Grid, kết hợp lập trình tương tác DOM mượt mà với JavaScript ES6+. Bao gồm đầy đủ video bài giảng, tài liệu đính kèm và đề trắc nghiệm đánh giá năng lực.', '2000.00', 'https://images.unsplash.com/photo-1507238691740-187a5b1d37b8?w=800&auto=format&fit=crop&q=80', 1, 2, 'instructor.frontend@eduflyup.vn', '2026-11-15 16:13:44.599526+00:00', '2026-11-15 16:13:44.599552+00:00', TRUE, 'Lập trình Frontend', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "Courses" ("Id", "Title", "Description", "Price", "ThumbnailUrl", "Level", "Status", "InstructorId", "CreatedAt", "UpdatedAt", "IsPublished", "Category", "RejectionReason") VALUES (9, 'Lập trình Backend với Node.js & Express.js Căn Bản (Test Certificate)', 'Khóa học tinh gọn chuẩn hóa kiến thức cốt lõi Node.js Runtime, NPM, Module System và Express RESTful API. Tích hợp bài thi Final Test 2 câu hỏi ngắn để kiểm tra chức năng cấp chứng chỉ tự động.', '10000.00', 'https://images.unsplash.com/photo-1627398242454-45a1465c2479?w=800&auto=format&fit=crop&q=80', 1, 2, 'c6f3b359-25d7-4e4c-903e-74808d561abe', '2026-11-16 00:56:21.711614+00:00', '2026-11-16 00:56:21.711614+00:00', TRUE, 'Backend Development', NULL) ON CONFLICT DO NOTHING;
