INSERT INTO "Lessons" ("Id", "Title", "Content", "VideoUrl", "DurationMinutes", "Order", "IsPreview", "CourseId", "CreatedAt", "UpdatedAt", "SectionName", "MaterialUrl", "AttachmentName") VALUES (27, 'Bài 1: Kiến trúc Node.js Runtime & V8 Engine', 'Tìm hiểu cơ chế hoạt động của Node.js, Non-blocking I/O, Event Loop và JavaScript Engine V8 được tích hợp từ Google.', 'https://www.youtube.com/watch?v=TlB_eWDSMt4', 10, 1, TRUE, 9, '2026-11-16 00:56:21.711614+00:00', '2026-11-16 00:56:21.711614+00:00', 'Chương 1: Tổng quan', '', '') ON CONFLICT DO NOTHING;
INSERT INTO "Lessons" ("Id", "Title", "Content", "VideoUrl", "DurationMinutes", "Order", "IsPreview", "CourseId", "CreatedAt", "UpdatedAt", "SectionName", "MaterialUrl", "AttachmentName") VALUES (28, 'Bài 2: Quản lý thư viện với NPM & Package.json', 'Hướng dẫn khởi tạo dự án Node.js với npm init, cài đặt gói phụ thuộc (dependencies) và cấu hình script khởi chạy.', 'https://www.youtube.com/watch?v=TlB_eWDSMt4', 12, 2, TRUE, 9, '2026-11-16 00:56:21.711614+00:00', '2026-11-16 00:56:21.711614+00:00', 'Chương 1: Tổng quan', '', '') ON CONFLICT DO NOTHING;
INSERT INTO "Lessons" ("Id", "Title", "Content", "VideoUrl", "DurationMinutes", "Order", "IsPreview", "CourseId", "CreatedAt", "UpdatedAt", "SectionName", "MaterialUrl", "AttachmentName") VALUES (29, 'Bài 3: Xây dựng RESTful API đầu tiên với Express.js', 'Tạo web server siêu tốc với Express Framework, định tuyến Router và trả về dữ liệu chuẩn JSON cho ứng dụng Client.', 'https://www.youtube.com/watch?v=TlB_eWDSMt4', 15, 3, TRUE, 9, '2026-11-16 00:56:21.711614+00:00', '2026-11-16 00:56:21.711614+00:00', 'Chương 1: Tổng quan', '', '') ON CONFLICT DO NOTHING;
