INSERT INTO "Questions" ("Id", "Content", "Difficulty", "InstructorId", "Explanation", "CreatedAt", "UpdatedAt", "CourseId", "Points") VALUES (3, 'Thẻ nào trong HTML5 dùng để định nghĩa một bài viết độc lập, có thể tái sử dụng hoặc phân phối riêng biệt (như bài blog, bài báo)?', 2, NULL, '<article> đại diện cho một khối nội dung độc lập hoàn chỉnh, phù hợp cho bài viết blog, tin tức hay bình luận.', '2026-11-15 16:16:27.153236+00:00', '2026-11-15 16:16:27.153272+00:00', 6, 1) ON CONFLICT DO NOTHING;
INSERT INTO "Questions" ("Id", "Content", "Difficulty", "InstructorId", "Explanation", "CreatedAt", "UpdatedAt", "CourseId", "Points") VALUES (4, 'Trong CSS Box Model, thuộc tính ''box-sizing: border-box;'' có ý nghĩa gì?', 2, NULL, 'Khi đặt box-sizing: border-box, chiều rộng (width) và chiều cao (height) sẽ bao gồm luôn cả phần padding và border, giúp layout không bị vỡ.', '2026-11-15 16:16:27.507650+00:00', '2026-11-15 16:16:27.507650+00:00', 6, 1) ON CONFLICT DO NOTHING;
INSERT INTO "Questions" ("Id", "Content", "Difficulty", "InstructorId", "Explanation", "CreatedAt", "UpdatedAt", "CourseId", "Points") VALUES (5, 'Trong CSS Flexbox, thuộc tính nào dùng để căn chỉnh các phần tử con dọc theo trục chính (Main Axis)?', 2, NULL, 'justify-content dùng để căn chỉnh phần tử theo trục chính (Main Axis), trong khi align-items căn chỉnh theo trục phụ (Cross Axis).', '2026-11-15 16:16:28.126332+00:00', '2026-11-15 16:16:28.126332+00:00', 6, 1) ON CONFLICT DO NOTHING;
INSERT INTO "Questions" ("Id", "Content", "Difficulty", "InstructorId", "Explanation", "CreatedAt", "UpdatedAt", "CourseId", "Points") VALUES (6, 'Sự khác biệt cốt lõi giữa toán tử ''=='' và ''==='' trong JavaScript là gì?', 2, NULL, 'Toán tử ''==='' (Strict equality) so sánh cả giá trị và kiểu dữ liệu, không tự động ép kiểu như ''==''.', '2026-11-15 16:16:28.728243+00:00', '2026-11-15 16:16:28.728243+00:00', 6, 1) ON CONFLICT DO NOTHING;
INSERT INTO "Questions" ("Id", "Content", "Difficulty", "InstructorId", "Explanation", "CreatedAt", "UpdatedAt", "CourseId", "Points") VALUES (7, 'Phương thức nào của Event Object trong JavaScript dùng để ngăn chặn hành vi mặc định của trình duyệt (ví dụ: ngăn trang reload khi submit form)?', 2, NULL, 'event.preventDefault() dùng để hủy bỏ hành vi mặc định của sự kiện nếu sự kiện đó có thể hủy bỏ.', '2026-11-15 16:16:29.323015+00:00', '2026-11-15 16:16:29.323015+00:00', 6, 1) ON CONFLICT DO NOTHING;
INSERT INTO "Questions" ("Id", "Content", "Difficulty", "InstructorId", "Explanation", "CreatedAt", "UpdatedAt", "CourseId", "Points") VALUES (8, 'Đoạn mã ES6 sau cho kết quả gì: const [a, , b] = [10, 20, 30]; console.log(a, b);', 2, NULL, 'Cú pháp destructuring mảng bỏ qua phần tử thứ hai (dấu phẩy trống), do đó a = 10 và b = 30.', '2026-11-15 16:16:29.921467+00:00', '2026-11-15 16:16:29.921467+00:00', 6, 1) ON CONFLICT DO NOTHING;
INSERT INTO "Questions" ("Id", "Content", "Difficulty", "InstructorId", "Explanation", "CreatedAt", "UpdatedAt", "CourseId", "Points") VALUES (9, 'Trong CSS Grid, cú pháp nào sau đây giúp tạo ra các cột tự động co giãn theo chiều rộng màn hình mà không cần dùng Media Query?', 2, NULL, 'grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)) là mẫu Responsive Grid chuẩn hiện đại tự co dãn.', '2026-11-15 16:16:30.520065+00:00', '2026-11-15 16:16:30.520065+00:00', 6, 1) ON CONFLICT DO NOTHING;
INSERT INTO "Questions" ("Id", "Content", "Difficulty", "InstructorId", "Explanation", "CreatedAt", "UpdatedAt", "CourseId", "Points") VALUES (10, 'Phạm vi hoạt động (Scope) của biến khai báo bằng từ khóa ''let'' và ''const'' trong JavaScript là gì?', 2, NULL, '''let'' và ''const'' có phạm vi khối (Block scope - bên trong cặp dấu ngoặc nhọn {}), trong khi ''var'' có phạm vi hàm (Function scope).', '2026-11-15 16:16:31.126393+00:00', '2026-11-15 16:16:31.126393+00:00', 6, 1) ON CONFLICT DO NOTHING;
INSERT INTO "Questions" ("Id", "Content", "Difficulty", "InstructorId", "Explanation", "CreatedAt", "UpdatedAt", "CourseId", "Points") VALUES (11, 'Phương thức nào dùng để chuyển đổi một chuỗi văn bản định dạng JSON thành Object trong JavaScript?', 2, NULL, 'JSON.parse() chuyển chuỗi JSON thành JavaScript Object, còn JSON.stringify() làm ngược lại.', '2026-11-15 16:16:31.732284+00:00', '2026-11-15 16:16:31.732284+00:00', 6, 1) ON CONFLICT DO NOTHING;
INSERT INTO "Questions" ("Id", "Content", "Difficulty", "InstructorId", "Explanation", "CreatedAt", "UpdatedAt", "CourseId", "Points") VALUES (12, 'Thuộc tính nào của thẻ <img> trong HTML5 là bắt buộc để hỗ trợ công nghệ đọc màn hình cho người khiếm thị và chuẩn SEO?', 2, NULL, 'Thuộc tính alt (alternative text) mô tả nội dung hình ảnh, là tiêu chuẩn tối quan trọng cho SEO và Accessibility (A11y).', '2026-11-15 16:16:32.349416+00:00', '2026-11-15 16:16:32.349416+00:00', 6, 1) ON CONFLICT DO NOTHING;
INSERT INTO "Questions" ("Id", "Content", "Difficulty", "InstructorId", "Explanation", "CreatedAt", "UpdatedAt", "CourseId", "Points") VALUES (14, 'Node.js được xây dựng dựa trên JavaScript Engine nào của Google Chrome?', 1, NULL, 'Node.js được xây dựng trên JavaScript V8 Engine của Google Chrome để biên dịch JavaScript trực tiếp sang mã máy.', '2026-11-16 00:56:21.711614+00:00', '2026-11-16 00:56:21.711614+00:00', 9, 10) ON CONFLICT DO NOTHING;
INSERT INTO "Questions" ("Id", "Content", "Difficulty", "InstructorId", "Explanation", "CreatedAt", "UpdatedAt", "CourseId", "Points") VALUES (15, 'Lệnh nào trong Terminal được dùng để khởi tạo file package.json cho dự án Node.js?', 1, NULL, 'Lệnh ''npm init'' (hoặc npm init -y) dùng để tạo tệp cấu hình package.json cho dự án Node.js mới.', '2026-11-16 00:56:21.711614+00:00', '2026-11-16 00:56:21.711614+00:00', 9, 10) ON CONFLICT DO NOTHING;
