INSERT INTO "Quizzes" ("Id", "CourseId", "Title", "Description", "DurationMinutes", "PassingScore", "IsActive", "CreatedAt", "UpdatedAt", "IsCAT", "PassingScorePercentage") VALUES (1, 6, 'Bài kiểm tra Trắc nghiệm Đánh giá Năng lực Frontend (HTML/CSS/JS)', 'Đề thi gồm 10 câu hỏi trắc nghiệm đánh giá tư duy ngữ nghĩa HTML5, kỹ năng layout CSS Flexbox/Grid và logic JavaScript ES6+. Thời gian làm bài 20 phút, điểm đạt tối thiểu 70%.', 20, 70, TRUE, '2026-11-15 16:13:46.272014+00:00', '2026-11-15 16:13:46.272014+00:00', FALSE, 70) ON CONFLICT DO NOTHING;
INSERT INTO "Quizzes" ("Id", "CourseId", "Title", "Description", "DurationMinutes", "PassingScore", "IsActive", "CreatedAt", "UpdatedAt", "IsCAT", "PassingScorePercentage") VALUES (4, 9, 'Bài thi tốt nghiệp tổng hợp (Final Test) - Node.js Core', 'Đề thi tốt nghiệp tổng hợp 2 câu hỏi ngắn gọn kiểm tra kiến thức Node.js cốt lõi. Đạt từ 95% (2/2 câu đúng) trở lên để được hệ thống tự động cấp Chứng chỉ tốt nghiệp.', 15, 70, TRUE, '2026-11-16 00:56:21.711614+00:00', '2026-11-16 00:56:21.711614+00:00', FALSE, 95) ON CONFLICT DO NOTHING;
